<template>
  <div class="category-view bg-light min-vh-100">
    <NavBarVue />

    <b-container fluid class="py-4">
      <b-row>
        <b-col lg="8" md="12" class="mb-4">
          <b-card no-body class="shadow-sm border-0 h-100">
            <b-card-header class="bg-white border-bottom-0 pt-4 px-4">
              <b-row align-v="center">
                <b-col md="4">
                  <h5 class="text-mbr-green font-weight-bold mb-0">
                    <b-icon icon="people-fill" class="mr-2"></b-icon>
                    Mutuários: {{ customersPagination.totalItems }}
                  </h5>
                </b-col>
                <b-col md="4">
                  <b-input-group size="sm">
                    <b-input-group-prepend
                      is-text
                      class="bg-light border-right-0"
                    >
                      <b-icon icon="search" variant="secondary"></b-icon>
                    </b-input-group-prepend>
                    <b-form-input
                      type="text"
                      class="border-left-0 bg-light"
                      v-model="searchValues"
                      @input="onSearchInput"
                      placeholder="Pesquisar por nome, telefone, NUIT..."
                    ></b-form-input>
                    <b-input-group-append v-if="searchValues">
                      <b-button
                        variant="outline-secondary"
                        size="sm"
                        @click="clearSearch"
                        title="Limpar pesquisa"
                      >
                        <b-icon icon="x"></b-icon>
                      </b-button>
                    </b-input-group-append>
                    </b-input-group>
                  </b-col>
                  <b-col md="4" class="text-right mt-2 mt-md-0">
                  <b-button-group size="sm" class="mr-2">
                    <b-button
                      variant="outline-info"
                      @click="downloadExcelTemplate()"
                      title="Baixar template Excel"
                    >
                      <b-icon icon="download" class="mr-1"></b-icon>
                      Template
                    </b-button>
                    <b-button
                      variant="outline-primary"
                      @click="$refs.excelFileInput.click()"
                      title="Importar mutuários via Excel"
                      :disabled="isLoading"
                    >
                      <b-icon icon="upload" class="mr-1"></b-icon>
                      Importar
                    </b-button>
                  </b-button-group>
                  <input
                    type="file"
                    ref="excelFileInput"
                    accept=".xlsx,.xls"
                    class="d-none"
                    @change="onExcelFileSelected"
                  />
                  <b-button-group size="sm">
                    <b-button
                      variant="outline-danger"
                      @click="downloadCustomerList()"
                      title="PDF"
                    >
                      <b-icon icon="file-earmark-pdf-fill"></b-icon>
                    </b-button>
                    <b-button
                      variant="outline-success"
                      @click="downloadCustomerListExcel()"
                      title="Excel"
                    >
                      <b-icon icon="file-earmark-excel-fill"></b-icon>
                    </b-button>
                    <b-button
                      variant="outline-secondary"
                      @click="refreshCustomers()"
                      title="Atualizar"
                    >
                      <b-icon icon="arrow-clockwise"></b-icon>
                    </b-button>
                  </b-button-group>
                </b-col>
              </b-row>
              <b-row class="mt-2" align-v="center">
                <b-col md="6" lg="5">
                  <b-input-group size="sm">
                    <b-input-group-prepend
                      is-text
                      class="bg-light border-right-0"
                    >
                      <b-icon icon="geo-alt" variant="secondary"></b-icon>
                    </b-input-group-prepend>
                    <b-form-input
                      v-model="bairroFilter"
                      type="text"
                      class="border-left-0 bg-light"
                      placeholder="Filtrar por bairro..."
                      @input="onBairroFilterInput"
                    ></b-form-input>
                    <b-input-group-append v-if="bairroFilter">
                      <b-button
                        variant="outline-secondary"
                        size="sm"
                        @click="clearBairroFilter"
                        title="Limpar filtro de bairro"
                      >
                        <b-icon icon="x"></b-icon>
                      </b-button>
                    </b-input-group-append>
                  </b-input-group>
                </b-col>
              </b-row>
            </b-card-header>

            <b-card-body class="px-0">
              <b-overlay :show="isLoading" rounded="sm">
                <div
                  v-if="customers.length == 0"
                  class="text-center py-5 text-muted"
                >
                  <b-icon icon="inbox" font-scale="3" class="mb-3"></b-icon>
                  <p>Nenhum mutuário encontrado.</p>
                </div>

                <div v-else class="table-responsive">
                  <table class="table table-hover align-middle mb-0">
                    <thead class="bg-light text-secondary">
                      <tr style="font-size: 0.9rem">
                        <th class="pl-4 border-top-0">Nome Completo</th>
                        <th class="border-top-0">Nº Mutuário</th>
                        <th class="border-top-0">Telefone</th>
                        <th class="border-top-0">Bairro</th>
                        <th class="text-center border-top-0" width="150">
                          Ações
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="customer in customers"
                        :key="customer.id"
                        class="cursor-pointer"
                        :class="{ 'table-warning': form.id === customer.id }"
                        @click="updateCustomer(customer)"
                      >
                        <td class="pl-4">
                          <div class="font-weight-bold text-dark">
                            {{ customer.customerName }}
                          </div>
                          <small class="text-muted">{{
                            customer.customerEmail
                          }}</small>
                        </td>
                        <td class="align-middle">
                          <span class="badge badge-light border">{{
                            customer.accountNumber
                          }}</span>
                        </td>
                        <td class="align-middle">
                          {{ customer.customerPhone }}
                        </td>
                        <td class="align-middle">
                          {{ customer.customerBairro || "—" }}
                        </td>
                        <td class="text-center align-middle">
                          <b-button
                            size="sm"
                            variant="link"
                            class="text-danger p-1"
                            @click.stop="deleteCustomer(customer.id)"
                          >
                            <b-icon icon="trash"></b-icon>
                          </b-button>
                          <b-button
                            size="sm"
                            variant="link"
                            class="text-mbr-green p-1"
                            @click.stop="updateCustomer(customer)"
                          >
                            <b-icon icon="pencil-square"></b-icon>
                          </b-button>
                          <b-button
                            size="sm"
                            variant="link"
                            class="text-info p-1"
                            @click.stop="openCustomerPanel(customer)"
                          >
                            <b-icon icon="eye"></b-icon>
                          </b-button>
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </b-overlay>

              <!-- Controles de Paginação -->
              <div
                v-if="customersPagination.totalPages > 0"
                class="d-flex justify-content-between align-items-center px-4 py-3 border-top"
              >
                <div class="d-flex align-items-center">
                  <small class="text-muted mr-2">Mostrar</small>
                  <b-form-select
                    size="sm"
                    v-model="perPage"
                    :options="perPageOptions"
                    style="width: 75px"
                    @change="onPerPageChange"
                  ></b-form-select>
                  <small class="text-muted ml-2">por página</small>
                </div>

                <div class="text-center">
                  <small class="text-muted">
                    Mostrando
                    <strong>{{ paginationStart }}</strong> -
                    <strong>{{ paginationEnd }}</strong>
                    de
                    <strong>{{ customersPagination.totalItems }}</strong>
                    mutuários
                  </small>
                </div>

                <nav aria-label="Navegação de páginas">
                  <ul class="pagination pagination-sm mb-0">
                    <li
                      class="page-item"
                      :class="{ disabled: !customersPagination.hasPrevPage }"
                    >
                      <a
                        class="page-link"
                        href="#"
                        @click.prevent="goToPage(1)"
                        title="Primeira"
                      >
                        <b-icon icon="chevron-double-left" font-scale="0.8"></b-icon>
                      </a>
                    </li>
                    <li
                      class="page-item"
                      :class="{ disabled: !customersPagination.hasPrevPage }"
                    >
                      <a
                        class="page-link"
                        href="#"
                        @click.prevent="goToPage(customersPagination.currentPage - 1)"
                        title="Anterior"
                      >
                        <b-icon icon="chevron-left" font-scale="0.8"></b-icon>
                      </a>
                    </li>

                    <li
                      v-for="page in visiblePages"
                      :key="page"
                      class="page-item"
                      :class="{ active: page === customersPagination.currentPage }"
                    >
                      <a
                        class="page-link"
                        href="#"
                        @click.prevent="goToPage(page)"
                      >
                        {{ page }}
                      </a>
                    </li>

                    <li
                      class="page-item"
                      :class="{ disabled: !customersPagination.hasNextPage }"
                    >
                      <a
                        class="page-link"
                        href="#"
                        @click.prevent="goToPage(customersPagination.currentPage + 1)"
                        title="Próxima"
                      >
                        <b-icon icon="chevron-right" font-scale="0.8"></b-icon>
                      </a>
                    </li>
                    <li
                      class="page-item"
                      :class="{ disabled: !customersPagination.hasNextPage }"
                    >
                      <a
                        class="page-link"
                        href="#"
                        @click.prevent="goToPage(customersPagination.totalPages)"
                        title="Última"
                      >
                        <b-icon icon="chevron-double-right" font-scale="0.8"></b-icon>
                      </a>
                    </li>
                  </ul>
                </nav>
              </div>
            </b-card-body>
          </b-card>
        </b-col>

        <b-col lg="4" md="12">
          <b-card
            class="shadow-sm border-0 sticky-top"
            style="top: 20px; z-index: 1"
          >
            <div class="d-flex justify-content-between align-items-center mb-3">
              <h6 class="font-weight-bold text-mbr-green mb-0">
                <b-icon icon="person-plus-fill" class="mr-1"></b-icon>
                {{
                  customerUpdationId == 0 ? "Novo Mutuário" : "Editar Mutuário"
                }}
              </h6>
              <b-button
                v-if="customerUpdationId != 0"
                size="sm"
                variant="light"
                @click="resetFields()"
              >
                Cancelar
              </b-button>
            </div>

            <b-form @submit.prevent="registerNewCustomer">
              <div class="section-label">Dados Pessoais</div>
              <b-form-group class="mb-2">
                <small class="form-field-label">Nome completo</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerName"
                  placeholder="Ex.: Ana Maria Silva"
                  required
                ></b-form-input>
              </b-form-group>

              <b-row class="mb-2">
                <b-col cols="6" class="pr-1">
                  <small class="form-field-label">Sexo</small>
                  <b-form-select
                    size="sm"
                    v-model="form.sex"
                    :options="gender"
                    required
                  ></b-form-select>
                </b-col>
                <b-col cols="6" class="pl-1">
                  <small class="form-field-label">Data de nascimento</small>
                  <b-form-input
                    type="date"
                    size="sm"
                    v-model="form.customerDateOfBirth"
                    placeholder="AAAA-MM-DD"
                  ></b-form-input>
                </b-col>
              </b-row>

              <div class="section-label mt-3">Contactos</div>
              <b-row class="mb-2">
                <b-col cols="6" class="pr-1">
                  <small class="form-field-label">Telemóvel principal</small>
                  <b-form-input
                    type="tel"
                    size="sm"
                    v-model="form.customerPhone"
                    placeholder="Ex.: 84XXXXXXX"
                    required
                  ></b-form-input>
                </b-col>
                <b-col cols="6" class="pl-1">
                  <small class="form-field-label">E-mail</small>
                  <b-form-input
                    type="email"
                    size="sm"
                    v-model="form.customerEmail"
                    placeholder="Ex.: cliente@email.com"
                  ></b-form-input>
                </b-col>
              </b-row>
              <b-form-group class="mb-2">
                <small class="form-field-label">Endereço / residência</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerAddress"
                  placeholder="Ex.: Rua, nº"
                ></b-form-input>
              </b-form-group>
              <b-form-group class="mb-2">
                <small class="form-field-label">Bairro</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerBairro"
                  placeholder="Ex.: Mukhatine"
                ></b-form-input>
              </b-form-group>

              <div class="section-label mt-3">Documentação</div>
              <b-row class="mb-2">
                <b-col cols="6" class="pr-1">
                  <small class="form-field-label">NUIT</small>
                  <b-form-input
                    size="sm"
                    v-model="form.customerNuit"
                    placeholder="Ex.: 123456789"
                  ></b-form-input>
                </b-col>
                <b-col cols="6" class="pl-1">
                  <small class="form-field-label">Nº BI/Passaporte</small>
                  <b-form-input
                    size="sm"
                    v-model="form.customerNationalId"
                    placeholder="Ex.: 123456789A"
                  ></b-form-input>
                </b-col>
              </b-row>
              <b-row class="mb-2">
                <b-col cols="6" class="pr-1">
                  <small class="form-field-label">Data de emissão</small>
                  <b-form-input
                    type="date"
                    size="sm"
                    v-model="form.issuedAt"
                    placeholder="AAAA-MM-DD"
                  ></b-form-input>
                </b-col>
                <b-col cols="6" class="pl-1">
                  <small class="form-field-label">Local de emissão</small>
                  <b-form-input
                    size="sm"
                    v-model="form.localOfIssue"
                    placeholder="Ex.: Maputo"
                  ></b-form-input>
                </b-col>
              </b-row>

              <div class="section-label mt-3">Dados Profissionais</div>
              <b-row class="mb-2">
                <b-col cols="6" class="pr-1">
                  <small class="form-field-label">Profissão</small>
                  <b-form-input
                    size="sm"
                    v-model="form.customerProfession"
                    placeholder="Ex.: Comerciante"
                  ></b-form-input>
                </b-col>
                <b-col cols="6" class="pl-1">
                  <small class="form-field-label">Rendimento mensal</small>
                  <b-input-group size="sm">
                    <b-input-group-prepend is-text class="px-1 text-muted"
                      >MZN</b-input-group-prepend
                    >
                    <b-form-input
                      type="number"
                      v-model="form.customerMonthlySalary"
                      placeholder="Ex.: 15000"
                    ></b-form-input>
                  </b-input-group>
                </b-col>
              </b-row>
              <b-form-group class="mb-2">
                <small class="form-field-label">Entidade patronal / local de trabalho</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerLocalOfWork"
                  placeholder="Ex.: Empresa X"
                ></b-form-input>
              </b-form-group>

              <div class="section-label mt-3">Familiar / Emergência</div>
              <b-form-group class="mb-2">
                <small class="form-field-label">Estado civil</small>
                <b-form-select
                  size="sm"
                  v-model="form.maritalStatus"
                  :options="maritalStatus"
                  required
                ></b-form-select>
              </b-form-group>

              <div
                v-if="form.maritalStatus == 'casado'"
                class="bg-light p-2 rounded mb-2"
              >
                <small class="form-field-label">Nome do cônjuge</small>
                <b-form-input
                  size="sm"
                  class="mb-1"
                  v-model="form.customerSpouseName"
                  placeholder="Ex.: Maria Silva"
                ></b-form-input>
                <small class="form-field-label">Contacto do cônjuge</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerSpouseContact"
                  placeholder="Ex.: 84XXXXXXX"
                ></b-form-input>
              </div>

              <div
                v-if="form.maritalStatus && form.maritalStatus != 'casado'"
                class="bg-light p-2 rounded mb-2"
              >
                <small class="form-field-label">Pessoa de contacto</small>
                <b-form-input
                  size="sm"
                  class="mb-1"
                  v-model="form.customerEmergencyPerson"
                  placeholder="Ex.: João Silva"
                ></b-form-input>
                <small class="form-field-label">Telefone de emergência</small>
                <b-form-input
                  size="sm"
                  v-model="form.customerEmergencyContact"
                  placeholder="Ex.: 84XXXXXXX"
                ></b-form-input>
              </div>

              <div class="mt-4 pt-2 border-top">
                <b-row>
                  <b-col cols="5">
                    <b-button
                      block
                      variant="outline-secondary"
                      size="sm"
                      @click="resetFields"
                      :disabled="isLoading"
                    >
                      Limpar
                    </b-button>
                  </b-col>
                  <b-col cols="7">
                    <b-button
                      block
                      class="btn-mbr-primary text-white border-0"
                      size="sm"
                      type="submit"
                      :disabled="isLoading"
                    >
                      <b-icon icon="check2-circle"></b-icon>
                      {{ customerUpdationId == 0 ? "Cadastrar" : "Salvar" }}
                    </b-button>
                  </b-col>
                </b-row>
              </div>
            </b-form>
          </b-card>
        </b-col>
      </b-row>
    </b-container>

    <b-modal
      hide-footer
      centered
      ref="delete-customer"
      title="Confirmar Exclusão"
      header-bg-variant="danger"
      header-text-variant="white"
    >
      <div class="text-center py-3">
        <b-icon
          icon="exclamation-circle"
          variant="danger"
          font-scale="3"
          class="mb-3"
        ></b-icon>
        <h5>Tem certeza?</h5>
        <p class="text-muted">Esta ação removerá o mutuário permanentemente.</p>
      </div>
      <b-row>
        <b-col>
          <b-button block variant="secondary" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block variant="danger" @click="decidedToDelete()"
            >Sim, Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
// A SEÇÃO DE SCRIPT PERMANECE PRATICAMENTE A MESMA
// Mantendo toda a sua lógica de negócio intacta.

import { mapGetters } from "vuex";
import axios from "axios";
import moment from "moment";
moment.locale("pt-br");
import DateFormat from "../utils/dateFormat";
import NavBarVue from "@/components/NavBar";
import exportFromJSON from "export-from-json";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import * as XLSX from "xlsx";

export default {
  name: "CustomerComponent",
  components: { NavBarVue },
  data: () => ({
    searchValues: "",
    bairroFilter: "",
    searchTimeout: null,
    perPage: 15,
    perPageOptions: [
      { value: 10, text: "10" },
      { value: 15, text: "15" },
      { value: 25, text: "25" },
      { value: 50, text: "50" },
      { value: 100, text: "100" },
    ],
    form: {
      customerName: "",
      sex: null,
      customerEmail: "",
      customerPhone: "",
      customerNuit: "",
      customerNationalId: "",
      issuedAt: "",
      localOfIssue: "",
      customerDateOfBirth: "", // Certifique-se que existe este campo no backend ou remova se não usar
      customerMonthlySalary: 0,
      customerAddress: "",
      customerBairro: "",
      customerProfession: "",
      customerLocalOfWork: "",
      maritalStatus: null,
      customerSpouseName: "",
      customerSpouseContact: "",
      customerEmergencyPerson: "",
      customerEmergencyContact: "",
      customerStatus: 0,
      interestRateId: 0,
    },
    maritalStatus: [
      { text: "Selecione o Estado Civil", value: null },
      { text: "Solteiro(a)", value: "solteiro" },
      { text: "Casado(a)", value: "casado" },
      { text: "Divorciado(a)", value: "divorciado" },
      { text: "Viúvo(a)", value: "viúvo" },
    ],
    gender: [
      { text: "Gênero", value: null },
      { text: "Masculino", value: "M" },
      { text: "Feminino", value: "F" },
    ],
    customerUpdationId: 0,
  }),

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "customers",
      "customersPagination",
      "company",
      "interestRates",
    ]),

    paginationStart() {
      if (this.customersPagination.totalItems === 0) return 0;
      return (this.customersPagination.currentPage - 1) * this.customersPagination.itemsPerPage + 1;
    },

    paginationEnd() {
      const end = this.customersPagination.currentPage * this.customersPagination.itemsPerPage;
      return Math.min(end, this.customersPagination.totalItems);
    },

    visiblePages() {
      const total = this.customersPagination.totalPages;
      const current = this.customersPagination.currentPage;
      const maxVisible = 5;
      const pages = [];

      if (total <= maxVisible) {
        for (let i = 1; i <= total; i++) pages.push(i);
      } else {
        let start = Math.max(1, current - Math.floor(maxVisible / 2));
        let end = start + maxVisible - 1;

        if (end > total) {
          end = total;
          start = Math.max(1, end - maxVisible + 1);
        }

        for (let i = start; i <= end; i++) pages.push(i);
      }

      return pages;
    },
  },

  created() {
    // Verificações iniciais
    if (this.user && this.user.updatedPassword !== 1) {
      this.$router.replace("/profile");
    }
  },

  methods: {
    fetchCustomers(page = 1) {
      this.$store.dispatch("getAllCustomers", {
        companyId: this.company.id,
        page: page,
        limit: this.perPage,
        search: this.searchValues.trim(),
        bairro: this.bairroFilter.trim(),
      });
    },

    onSearchInput() {
      clearTimeout(this.searchTimeout);
      this.searchTimeout = setTimeout(() => {
        this.fetchCustomers(1);
      }, 400);
    },

    onBairroFilterInput() {
      clearTimeout(this.searchTimeout);
      this.searchTimeout = setTimeout(() => {
        this.fetchCustomers(1);
      }, 400);
    },

    clearSearch() {
      this.searchValues = "";
      this.fetchCustomers(1);
    },

    clearBairroFilter() {
      this.bairroFilter = "";
      this.fetchCustomers(1);
    },

    goToPage(page) {
      if (page < 1 || page > this.customersPagination.totalPages) return;
      if (page === this.customersPagination.currentPage) return;
      this.fetchCustomers(page);
    },

    onPerPageChange() {
      this.fetchCustomers(1); // Volta à página 1 ao alterar itens por página
    },

    openCustomerPanel(customer) {
      this.$store.commit("SET_CURRENT_CUSTOMER", customer);
      this.$router.replace("/customer");
    },

    refreshCustomers() {
      this.fetchCustomers(this.customersPagination.currentPage || 1);
    },

    deleteCustomer(id) {
      if (this.user.userRole > 1) {
        this.showToast(
          "Aviso!",
          "warning",
          "Você não tem permissão para apagar clientes."
        );
        return;
      }
      this.customerUpdationId = id;
      this.$refs["delete-customer"].show();
    },

    cancelDeletion() {
      this.customerUpdationId = 0;
      this.$refs["delete-customer"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/customer/${this.customerUpdationId}`)
        .then((res) => {
          if (res.data.success) {
            this.showToast("Sucesso!", "success", res.data.message);
            this.fetchCustomers(this.customersPagination.currentPage || 1);
          } else {
            this.showToast("Erro!", "warning", res.data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    updateCustomer(customer) {
      this.customerUpdationId = customer.id;
      // Clonar objeto para evitar reatividade direta na tabela antes de salvar
      this.form = { ...customer };

      // Scroll suave para o formulário no topo em mobile
      window.scrollTo({ top: 0, behavior: "smooth" });
    },

    registerNewCustomer() {
      // Validações básicas
      if (this.form.customerName.length < 6) {
        this.showToast(
          "Aviso",
          "warning",
          "Nome deve ter no mínimo 6 caracteres."
        );
        return;
      }
      if (
        !this.form.customerPhone ||
        this.form.customerPhone.toString().length < 9
      ) {
        // Ajustei validação para ser mais flexível (ex: 9 digitos Mz)
        this.showToast("Aviso", "warning", "Verifique o número de telemóvel.");
        return;
      }

      this.$store.commit("LOADING_STATUS", true);

      const payload = { ...this.form, companyId: this.company.id };
      const isNew = this.customerUpdationId === 0;
      const request = isNew
        ? axios.post("/api/customer", payload)
        : axios.put(`/api/customer/${this.customerUpdationId}`, payload);

      request
        .then((res) => {
          if (res.data.success) {
            this.fetchCustomers(this.customersPagination.currentPage || 1);
            this.showToast("Sucesso!", "success", res.data.message);
            this.resetFields();
          } else {
            this.showToast("Atenção", "danger", res.data.message);
          }
        })
        .catch((err) => {
          this.showToast("Erro de Sistema", "danger", err.message);
        })
        .finally(() => {
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    // MÉTODOS DE DOWNLOAD (PDF/EXCEL) MANTIDOS IGUAIS
    async downloadCustomerList() {
      const body = [];

      // Cabeçalho da Tabela no PDF com cores da MBR
      const tableHeader = [
        { text: "Nome do mutuário", style: "columnsTitle" },
        { text: "E-mail", style: "columnsTitle" },
        { text: "Telefone", style: "columnsTitle" },
        { text: "Bairro", style: "columnsTitle" },
        { text: "NUIT", style: "columnsTitle" },
        { text: "Profissão", style: "columnsTitle" },
        { text: "Data", style: "columnsTitle" },
      ];

      for (let row of this.customers) {
        const rows = [];
        rows.push({ text: row.customerName || "-", fontSize: 7 });
        rows.push({ text: row.customerEmail || "-", fontSize: 7 });
        rows.push({ text: row.customerPhone || "-", fontSize: 7 });
        rows.push({ text: row.customerBairro || "-", fontSize: 7 });
        rows.push({ text: row.customerNuit || "-", fontSize: 7 });
        rows.push({ text: row.customerProfession || "-", fontSize: 7 });
        rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 7 });
        body.push(rows);
      }

      let docDefinition = {
        footer: (currentPage, pageCount) => {
          return {
            columns: [
              {
                text: "Documento processado por computador",
                alignment: "left",
                fontSize: 7,
                margin: [40, 0, 0, 0],
                color: "#777",
              },
              {
                text: `Página ${currentPage} de ${pageCount}`,
                alignment: "right",
                fontSize: 7,
                margin: [0, 0, 40, 0],
                color: "#777",
              },
            ],
          };
        },

        content: [
          // Título do Relatório
          {
            text: "LISTA GERAL DE MUTUÁRIOS",
            style: "headerTitle",
            alignment: "center",
            margin: [0, 0, 0, 10],
          },
          {
            canvas: [
              {
                type: "line",
                x1: 0,
                y1: 5,
                x2: 515,
                y2: 5,
                lineWidth: 1,
                lineColor: "#009640",
              },
            ],
          },
          {
            columns: [
              {
                text: `Data de emissão: ${DateFormat.formatDate(new Date())}`,
                fontSize: 8,
                margin: [0, 10, 0, 10],
              },
              {
                text: `Total: ${this.customers.length} clientes`,
                fontSize: 8,
                alignment: "right",
                margin: [0, 10, 0, 10],
                bold: true,
              },
            ],
          },
          {
            table: {
              headerRows: 1,
              widths: ["*", "auto", "auto", "auto", "auto", "auto", "auto"],
              body: [tableHeader, ...body],
            },
            layout: {
              fillColor: function (rowIndex) {
                return rowIndex % 2 === 0 && rowIndex !== 0 ? "#f9f9f9" : null;
              },
              hLineColor: () => "#eee",
              vLineColor: () => "#eee",
            },
          },
        ],
        styles: {
          headerTitle: {
            fontSize: 14,
            bold: true,
            color: "#009640", // Verde MBR
          },
          columnsTitle: {
            fontSize: 8,
            bold: true,
            color: "#ffffff",
            fillColor: "#009640", // Fundo Verde MBR nas colunas
            margin: [2, 5, 2, 5],
          },
        },
      };

      pdfMake.createPdf(docDefinition).open();
    },

    downloadCustomerListExcel() {
      // ... (Mantenha sua lógica original aqui para Excel)
      const body = this.customers.map((c) => ({
        Nome: c.customerName,
        Telefone: c.customerPhone,
        Bairro: c.customerBairro || "",
        NUIT: c.customerNuit,
        Status: c.customerStatus,
      }));
      exportFromJSON({
        data: body,
        fileName: "Lista_Clientes",
        exportType: "xls",
      });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title: title,
        variant: variant,
        solid: true,
        autoHideDelay: 4000,
      });
    },

    resetFields() {
      this.customerUpdationId = 0;
      this.form = {
        customerName: "",
        sex: null,
        customerEmail: "",
        customerPhone: "",
        customerNuit: "",
        customerNationalId: "",
        issuedAt: "",
        localOfIssue: "",
        customerMonthlySalary: 0,
        customerAddress: "",
        customerBairro: "",
        customerProfession: "",
        customerLocalOfWork: "",
        maritalStatus: null,
        customerSpouseName: "",
        customerSpouseContact: "",
        customerEmergencyPerson: "",
        customerEmergencyContact: "",
        customerStatus: 0,
        interestRateId: 0,
      };
    },

    downloadExcelTemplate() {
      const headers = [
        "Nome Completo",
        "Género (M/F)",
        "Nº BI / Passaporte",
        "Data Emissão BI",
        "Local de Emissão",
        "Data de Nascimento",
        "NUIT",
        "Telefone",
        "Email",
        "Endereço",
        "Bairro",
        "Profissão",
        "Local de Trabalho",
        "Rendimento Mensal",
        "Estado Civil",
        "Nome do Cônjuge",
        "Contacto do Cônjuge",
        "Pessoa de Emergência",
        "Contacto de Emergência",
      ];

      const exampleRow = [
        "João Manuel Silva",
        "M",
        "123456789A",
        "2020-01-15",
        "Maputo",
        "1990-05-20",
        "100123456",
        "258841234567",
        "joao@email.com",
        "Av. Eduardo Mondlane, Maputo",
        "Central",
        "Comerciante",
        "Mercado Central",
        "15000",
        "casado",
        "Maria Silva",
        "258842345678",
        "Pedro Manuel",
        "258843456789",
      ];

      const ws = XLSX.utils.aoa_to_sheet([headers, exampleRow]);
      ws["!cols"] = headers.map(() => ({ wch: 22 }));
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Mutuários");
      XLSX.writeFile(wb, "Template_Cadastro_Mutuarios.xlsx");
      this.showToast("Sucesso", "success", "Template Excel descarregado.");
    },

    onExcelFileSelected(event) {
      const file = event.target.files[0];
      if (!file) return;

      this.$store.commit("LOADING_STATUS", true);
      const reader = new FileReader();

      reader.onload = (e) => {
        try {
          const data = new Uint8Array(e.target.result);
          const workbook = XLSX.read(data, { type: "array" });
          const sheetName = workbook.SheetNames[0];
          const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { defval: "" });

          if (rows.length === 0) {
            this.showToast("Aviso!", "warning", "O ficheiro Excel está vazio.");
            this.$store.commit("LOADING_STATUS", false);
            return;
          }

          const customers = rows.map((row) => ({
            customerName: row["Nome Completo"] || "",
            sex: (row["Género (M/F)"] || "M").toString().toUpperCase().charAt(0) === "F" ? "F" : "M",
            customerNationalId: (row["Nº BI / Passaporte"] || "").toString(),
            issuedAt: (row["Data Emissão BI"] || "").toString(),
            localOfIssue: (row["Local de Emissão"] || "").toString(),
            customerDateOfBirth: (row["Data de Nascimento"] || "").toString(),
            customerNuit: (row["NUIT"] || "").toString(),
            customerPhone: (row["Telefone"] || "").toString(),
            customerEmail: (row["Email"] || "").toString(),
            customerAddress: (row["Endereço"] || "").toString(),
            customerBairro: (row["Bairro"] || "").toString(),
            customerProfession: (row["Profissão"] || "").toString(),
            customerLocalOfWork: (row["Local de Trabalho"] || "").toString(),
            customerMonthlySalary: (row["Rendimento Mensal"] || "0").toString(),
            maritalStatus: (row["Estado Civil"] || "solteiro").toString().toLowerCase(),
            customerSpouseName: (row["Nome do Cônjuge"] || "").toString(),
            customerSpouseContact: (row["Contacto do Cônjuge"] || "").toString(),
            customerEmergencyPerson: (row["Pessoa de Emergência"] || "").toString(),
            customerEmergencyContact: (row["Contacto de Emergência"] || "").toString(),
          }));

          const valid = customers.filter((c) => String(c.customerName || "").trim().length > 0);

          if (valid.length === 0) {
            this.showToast("Aviso!", "warning", "Nenhum mutuário válido encontrado. Verifique se a coluna 'Nome Completo' está preenchida.");
            this.$store.commit("LOADING_STATUS", false);
            return;
          }

          this.bulkCreateCustomers(valid);
        } catch (err) {
          console.error("Erro ao processar Excel:", err);
          this.showToast("Erro!", "danger", "Erro ao processar o ficheiro Excel. Verifique o formato.");
          this.$store.commit("LOADING_STATUS", false);
        }
      };

      reader.readAsArrayBuffer(file);
      this.$refs.excelFileInput.value = "";
    },

    bulkCreateCustomers(customers) {
      axios
        .post("/api/customer/bulk", {
          companyId: this.company.id,
          customers,
        })
        .then((res) => {
          const data = res.data;
          if (data.success) {
            this.showToast("Sucesso!", "success", data.message);
            this.fetchCustomers(1);
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          console.error("Erro ao cadastrar mutuários:", err);
          this.showToast("Erro!", "danger", "Erro ao cadastrar mutuários em massa.");
          this.$store.commit("LOADING_STATUS", false);
        });
    },
  },
};
</script>

